-- Revisión del formato LOTO (29/10/2026): el LOTO base pasa a usar los textos del formato de referencia del dueño
-- (decisión del dueño: ajusta D-22 para LOTO). Se publica la versión 2 de la plantilla base y la 1 queda retirada.
-- Las copias que ya hicieron las empresas no cambian. No toca personas, empresas, roles ni permisos.
update public.plantillas_versiones v set estado = 'retirada'
from public.plantillas p where v.plantilla_id = p.id and p.empresa_id is null and p.codigo = 'loto' and v.estado = 'vigente';
with b as (select id from public.plantillas where empresa_id is null and codigo = 'loto'),
r as (select $j${"version":1,"firmas":[{"clave":"observado","titulo":"Observado","obligatoria":true,"externo":true,"minimo":1},{"clave":"responsable_area","titulo":"Responsable del área inspeccionada","obligatoria":true,"externo":false,"minimo":1},{"clave":"responsable_registro","titulo":"Responsable del registro e inspección","obligatoria":true,"externo":false,"minimo":1}],"reglas":[{"tipo":"x_en","etiqueta":"No conforme","alcance":"todos"}],"resultado_defecto":"Conforme","puntaje":true,"na_favorable":true,"hallazgo_vencimiento":false,"observacion_general":true,"secciones":[{"clave":"datos","titulo":"Datos de la inspección","puntos":[{"clave":"LOTO-D02","texto":"Tipo de bloqueo","tipo":"lista","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false,"lista":"tipos_bloqueo"},{"clave":"LOTO-D03","texto":"N° de trabajadores del centro laboral","tipo":"numero","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false}]},{"clave":"procedimiento","titulo":"PROCEDIMIENTO DE LOTO","puntos":[{"clave":"LOTO-01","texto":"¿El responsable de bloqueo conoce la importancia de LOTO?","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true},{"clave":"LOTO-02","texto":"¿El responsable de bloqueo identifica el mapa LOTO en el equipo? Según aplique.","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true},{"clave":"LOTO-03","texto":"¿El Responsable de Bloqueo está capacitado y autorizado para realizar el bloqueo del equipo?","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true},{"clave":"LOTO-04","texto":"¿El Responsable bloquea correctamente las fuentes de energía peligrosa? (Según el mapa LOTO)","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true},{"clave":"LOTO-05","texto":"¿Se verificó que el Responsable efectuara el bloqueo principal y que el personal de apoyo colocara correctamente su candado y tarjeta LOTO en la pinza o caja grupal, según aplique?","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true}]},{"clave":"equipo","titulo":"EQUIPO O MÁQUINA","puntos":[{"clave":"LOTO-06","texto":"¿El equipo o maquina cuenta con Mapa LOTO visible, en buen estado y la versión vigente?","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true},{"clave":"LOTO-07","texto":"¿Los puntos de bloqueo se encuentran accesibles?","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true},{"clave":"LOTO-08","texto":"¿Los puntos de bloqueo permite utilizarse para la tarea ejecutada?","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true}]},{"clave":"dispositivos","titulo":"DISPOSITIVOS DE BLOQUEO Y ETIQUETADO","puntos":[{"clave":"LOTO-09","texto":"¿Los dispositivos de bloqueo se encuentran en óptimas condiciones para su uso?","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true},{"clave":"LOTO-10","texto":"¿Tarjeta LOTO del trabajador se encuentra en buen estado?","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true},{"clave":"LOTO-11","texto":"¿Estación LOTO se encuentra limpia, ordenada y en buen estado?","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true},{"clave":"LOTO-12","texto":"¿Cuenta con los dispositivos de bloqueo completos? (según cartilla de estación LOTO)","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true}]}]}$j$::jsonb as receta)
insert into public.plantillas_versiones (plantilla_id, numero, estado, logo, receta, huella, publicado_en)
select b.id, (select coalesce(max(numero), 0) + 1 from public.plantillas_versiones where plantilla_id = b.id), 'vigente', 'positivo', r.receta,
  encode(extensions.digest(convert_to(r.receta::text, 'UTF8'), 'sha256'), 'hex'), now()
from b, r;
update public.plantillas set actualizado_en = now() where empresa_id is null and codigo = 'loto';
